\label{thm1}
Let the following conditions hold:
\begin{enumerate}
\item
\label{dn1}
the restriction $H|_{\Lambda_0}$ has a local non-degenerate extremum (maximum or minimum) $E_0$ at a point $z_0 = (p_0,x_0)$;

\item
\label{dn2}
$d H (z_0) \neq 0$;

\item
$z_\star = (p_\star, x_\star, t_\star, E_0) \in \Lambda$ is a point of the glancing trajectory $\mathcal{C}$ starting at the point $z_0$;

                                                                                                                                                                 
\item
\label{dn4}
the restriction
$$
\pi_{t}|_\Lambda : \Lambda \to \mathbb{R}^{n+1}_{t}
$$
is a local diffeomorphism of a neighborhood of the point $z_\star$ onto a neighborhood of the point $(x_\star, t_\star)$, i.\,e. $z_*$ is not a focal point.
\end{enumerate}
Then there exists a local canonical diffeomorphism $\gamma$ of $T^\ast \mathbb{R}^{n+1}_{t}$ defined in a neighborhood of the point $z_\star$
and satisfying the following conditions:
\begin{itemize}
\item
$\gamma: z_\star \mapsto 0$;
\item
$\gamma$ sends the fibres of the projection $\pi_{E}$ to each other;
\item
$\gamma$ sends the hypersurface $E=E_0$ to $E=0$;
\item
the Lagrangian submanifold $\Lambda' = \gamma (\Lambda)$ is given by the following equations
$$
S'(x,t) = t^3/3 + (x_2^2 + \dots + x_{n}^2) t,
\quad
E = - \partial_{t} S',
\quad
p = \partial_x S'
$$
in a neighborhood of the point $\gamma(z_\star) = 0$.
\end{itemize}

\label{assum}
\phantom{.}
\begin{enumerate}
\item
\label{cnd1}
The amplitude $a$ has a compact support $\mathop{\mathrm{supp}}\nolimits{a} \subset \Lambda_0$.
\item
\label{cnd2}
The phase flow $g^t$ of the Hamiltonian vector field $v_H$ generated by $H$
\begin{equation*}
           
g^t: T^\ast \mathbb{R}^n \to T^\ast \mathbb{R}^n, \quad \dot{x} = \partial_{p} H(p,x), \quad \dot{p}= - \partial_{x} H(p,x)
\end{equation*}
is defined for all $z \in \Lambda_0$, $t \ge 0$.
\item
\label{cnd3}
For any $R > 0$, there exists $t_R$ such that $\bigl| \pi \bigl( g^t(z) \bigr) \bigr| > R$ for all $t > t_R$ and $z \in \Lambda_0$, where
$$
\pi : T^\ast \mathbb{R}^n \to \mathbb{R}^n, \quad (p,x) \mapsto x
$$
is the natural projection.
In particular, all points of $\Lambda_0$ are not singular for the Hamiltonian vector field $v_H$: $d H (z_0) \neq 0$ for all $z_0 \in \Lambda_0$.
\end{enumerate}

If we write the initial amplitude in the form $a(x',x_n,\xi)$ (without eliminating $x$)
  we get instead
  \begin{equation*}
  u_h(x)={i\over h}\int_0^\infty\theta_T(t)\,dt\int^* e^{i(x'p'+(x_n-t)p_n)/h}e^{itE/h}a(x',x_n-t,p;h)\,dp
  \end{equation*}

Let $\Lambda_0$ be the $n$-dimensional Bessel cylinder (\ref{BC}) and $H\in C^\infty(T^*\mathbb{R}^n)$ be homogeneous
    of degree $m$ with respect to $p$. Then $z=(x,p)\in\Lambda_0$ is a glancing point at energy $E$ if and only if
    \begin{equation}
    \label{gl2}
    \partial_p H(z) + \varphi\partial_x H(z) = m H\omega(\psi), \; \langle-\partial_x H(z), \omega(\psi) \rangle=0, \; H(z)=E
    \end{equation}

\label{prop2}
Let $H(x,p)$ be positively
homogeneous of degree 1 with respect to $p$.
Then
\begin{equation*}
\Phi(\theta, x, t) = \varphi + \lambda \langle P(\varphi, \psi, t) , x - X(\varphi, \psi, t) \rangle, \quad
\theta = (\lambda, \varphi, \psi) \in \mathbb{R}^{n+1}
\end{equation*}
is a generating family for
$\Lambda \subset T^\ast \mathbb{R}^{n+1}_\mathrm{t}$
at the points satisfying the inequality $\det(P,P_\psi)\neq0$,
which holds at least for small $t$ (because $\det(P,\partial_\psi P)=1$ for $t=0$). In particular, $\Phi$ satisfies
the initial condition $\Phi(\theta, 0, x)=\Phi_0(\theta,x)$.

Assume $\Lambda$ as above to be parameterized by a quadratic phase $\phi=\phi_0$.
In Cases (I), (II), (III) $\phi_0$ are one-parameter families taking values:
\begin{equation}            
  \begin{aligned}
&(I) \quad \phi_0(x)=\frac12(ax_1^2-2x_1x_2)\cr
&(II) \quad \phi_0(p)=\frac12(2p_1p_2+cp_2^2)\cr
    &(III) \quad \phi_0(x_2,p_1)=\frac12b(p_1+x_2)^2
  \end{aligned}
  \end{equation}
respectively, where $a,b,c\neq0$. The manifold $\Lambda$ is transverse to $F$ at $z=0$,
and the corresponding matrices $A_z(\Lambda,G),B_z(\Lambda,G)$ above are then given by:
\begin{equation}\label{3.5}
  \begin{aligned}
&(I) \quad  A_z=2\begin{pmatrix}1&a\\ a&a^2\end{pmatrix}, \quad B_z=2\begin{pmatrix}-a \\ 1\end{pmatrix}\cr
&(II) \quad A_z=2\begin{pmatrix}0&0\\ 0&1\end{pmatrix}, \quad B_z=2 \begin{pmatrix} 1 \\ 0 \end{pmatrix}\cr
&(III) \quad A_z=2\begin{pmatrix}0&0\\ 0&1\end{pmatrix}, \quad B_z=2 \begin{pmatrix} 1 \\ 0 \end{pmatrix}
  \end{aligned}
  \end{equation}
So with the notations of Definition 1.3, case (I) is of type (6) or (7) according
to $a^3+2a^2+1=0$ or not, while cases (II) and
and (III) are of type (6). \\

At last, Case (IV) does not occur.
